const scopedReviewButton=N('button','Run scoped source-review command (candidate)');
$('plan').after(scopedReviewButton);
const scopedHelp=N('details'),scopedHelpTitle=N('summary','Source-review command syntax');
scopedHelp.append(scopedHelpTitle,N('p','Use “Review respiratory sources for patient P-1002” or “Prepare behavioral source-review work for patients P-2002, P-2003”. To use the full roster, replace “for patient …” with “across all observed patients”. Add “excluding patient …” for exclusions. Respiratory and behavioral commands use the current received snapshot; other questions use Analyze population.','meta'));
