scopedReviewButton.onclick=async()=>{
 const id=++seq;scopedReviewButton.disabled=true;$('results').replaceChildren();
 $('status').textContent='Checking the exact command and patient scope locally…';
 try{
  // Never discard a filter just because this narrow command cannot compile it.
  if(['coverage','region','min-age','code-prefix','organization','date-start','date-end'].some(k=>$(k).value.trim())||$('date-basis').value!=='all_observed')throw Error('This candidate supports patient IDs and exclusions only. Use ordinary planning for the selected population or date filters.');
  const d=await workspaceFetch('/api/stack/compose',{question:scopedQuestion(),planning:'scoped_local_candidate'});
  if(id!==seq)return;
  renderGraph({...d,results:d.results.filter(r=>r.node.operation!=='worklist')});
  const area=N('article'),fields=N('div',undefined,'care-grid'),buyer=careField(fields,'Source-review buyer ID',careBuyer),save=N('button','Connect this scoped question to buyer services and work'),out=N('div');
  area.append(N('h2','Continue the exact scoped question'),N('p','Experimental local command compiler · no hosted planning. This is documentary review; clinical need and benefits remain unresolved.','scope-notice'),details('Preserved question, patient scope and compiler receipt',{request:d.decision_seed,receipt:d.planner_receipt}),fields,save,out);
  const work=d.results.find(r=>r.node.operation==='worklist');if(work)area.append(details('Internal work proposal; no tasks dispatched',work.result));
  $('results').append(area);$('status').textContent='Scoped command completed locally · 0 new paid API calls · candidate remains explicit.';
  save.onclick=async()=>{save.disabled=true;try{
   const decision=await workspaceFetch('/api/stack/decision/scoped-prepare',{question:d.question,buyer_id:buyer.value.trim(),as_of:d.decision_seed.as_of,compiler_identity:d.planner_receipt.compiler_identity});
   await renderQuestionDecision(out,decision.id);
  }catch(e){out.replaceChildren(N('p',e.message,'missing'))}finally{save.disabled=false}};
 }catch(e){if(id===seq)$('status').textContent=e.message}finally{scopedReviewButton.disabled=false}
};

